/**
 * The technical due-diligence checklist (lead magnet). Feeds the /checklist
 * page and the PDFs generated by scripts/generate-checklist-pdf.ts at build.
 * 25 points, grouped the way investors' technical reviewers usually work.
 */

import type { Locale } from "@/lib/i18n";

export type ChecklistItem = {
  title: string;
  /** What a good answer looks like. */
  check: string;
  /** What makes a reviewer nervous. */
  redFlag: string;
};

export type ChecklistSection = {
  id: string;
  title: string;
  items: ChecklistItem[];
};

export type Checklist = {
  title: string;
  subtitle: string;
  intro: string;
  checkLabel: string;
  redFlagLabel: string;
  sections: ChecklistSection[];
  outro: string;
};

/** Published file name per locale, under /public/downloads. */
export const checklistPdf: Record<Locale, string> = {
  en: "/downloads/technical-due-diligence-checklist.pdf",
  fr: "/downloads/checklist-due-diligence-technique.pdf",
};

